variables.input:
fetch events, bucket:{"default_network_flows"}
| filter network_flow.process_is_server == true
| filter in(toString(network_flow.destination.port), array("88", "389", "3268"))
| summarize count(), by:{host.name}
| fields host.name
| sort host.name asc

fetch events, bucket:{"default_network_flows"}
| filter in(toString(network_flow.destination.port), array($AdPort))
| summarize count(), by:{host.name}
| fields host.name
| sort host.name asc

103.query:
fetch events, bucket:{"default_network_flows"}
| filter in(host.name, array($DC))
| limit 5
